+    printf("%s: wakeups=%d accepted=%d EWOULDBLOCK=%d\n",
+           exclusive ? "EPOLLEXCLUSIVE" : "baseline", wakes, accepts, blocks);
+    *observed_wouldblock = blocks;
+    if (exclusive)
+        return wakes == 1 && blocks == 0 ? 0 : 1;
+    return wakes >= 2 && blocks == wakes - 1 ? 0 : 1;
