#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#define WORKERS 4
#define CONNECTIONS 240
struct counts { atomic_int wakeups, accepts, wouldblock, errors, workers_active; };
static void die(const char *s) { perror(s); _exit(90); }
static int listener(int port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0), one = 1;
    if (fd < 0) die("socket");
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one))) die("SO_REUSEPORT");
    struct sockaddr_in a = {.sin_family=AF_INET,.sin_port=htons(port),.sin_addr.s_addr=htonl(INADDR_LOOPBACK)};
    if (bind(fd,(struct sockaddr*)&a,sizeof(a)) || listen(fd,128)) die("bind/listen");
    return fd;
}
static void worker(int port, int exclusive, struct counts *c, int shared_fd) {
    int fd=shared_fd>=0?shared_fd:listener(port), ep=epoll_create1(0); struct epoll_event ev={.events=EPOLLIN|(exclusive?EPOLLEXCLUSIVE:0),.data.fd=fd}, out[8];
    if(ep<0 || epoll_ctl(ep,EPOLL_CTL_ADD,fd,&ev)) die("epoll registration");
    atomic_fetch_add(&c->workers_active,1);
    for(;;) {
        int n=epoll_wait(ep,out,8,15000); if(n<0){if(errno==EINTR)continue;die("epoll_wait");}
        if(n==0) _exit(91);
        for(int i=0;i<n;i++) {
            atomic_fetch_add(&c->wakeups,1);
            int accepted_this_wakeup=0;
            for(;;) {
                int s=accept4(fd,0,0,SOCK_NONBLOCK);
                if(s>=0){accepted_this_wakeup++;atomic_fetch_add(&c->accepts,1); char b[16]; (void)read(s,b,sizeof(b)); close(s); continue;}
                if(errno==EAGAIN||errno==EWOULDBLOCK){if(!accepted_this_wakeup)atomic_fetch_add(&c->wouldblock,1);break;}
                if(errno==EINTR) continue;
                atomic_fetch_add(&c->errors,1);
                break;
            }
        }
    }
}
int main(int argc,char **argv) {
    int exclusive=argc>1&&!strcmp(argv[1],"exclusive");
    struct counts *c=mmap(0,sizeof(*c),PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANONYMOUS,-1,0); if(c==MAP_FAILED)die("mmap");
    int probe=listener(0); struct sockaddr_in a; socklen_t al=sizeof(a); if(getsockname(probe,(struct sockaddr*)&a,&al))die("getsockname"); int port=ntohs(a.sin_port); close(probe);
    int shared_fd=exclusive?-1:listener(port);
    pid_t pids[WORKERS]; for(int i=0;i<WORKERS;i++){pids[i]=fork();if(!pids[i])worker(port,exclusive,c,shared_fd);if(pids[i]<0)die("fork");}
    for(int i=0;i<100&&atomic_load(&c->workers_active)<WORKERS;i++){struct timespec t={0,10000000};nanosleep(&t,0);}
    for(int i=0;i<CONNECTIONS;i++) {
        int s=socket(AF_INET,SOCK_STREAM,0),one=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));
        a.sin_port=htons(port);a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_family=AF_INET;
        if(connect(s,(struct sockaddr*)&a,sizeof(a))) die("connect");
        if(write(s,"x",1)!=1) die("write");
        close(s);
    }
    for(int i=0;i<500&&atomic_load(&c->accepts)<CONNECTIONS;i++){struct timespec t={0,10000000};nanosleep(&t,0);}
    for(int i=0;i<WORKERS;i++) kill(pids[i],SIGKILL);
    for(int i=0;i<WORKERS;i++) while(waitpid(pids[i],0,0)<0&&errno==EINTR){}
    int w=atomic_load(&c->wakeups),ac=atomic_load(&c->accepts),wb=atomic_load(&c->wouldblock),er=atomic_load(&c->errors);
    printf("MODE=%s CONNECTIONS=%d WAKEUPS=%d ACCEPTS=%d EWOULDBLOCK=%d ERRORS=%d\n",exclusive?"EPOLLEXCLUSIVE":"LEGACY",CONNECTIONS,w,ac,wb,er);
    if(ac!=CONNECTIONS||er)return 2;
    if(exclusive&&wb!=0){puts("FAIL: exclusive registration still produced spurious empty wakeups");return 3;}
    if(!exclusive&&wb==0){puts("FAIL: negative control did not expose thundering herd");return 4;}
    puts(exclusive?"EPOLL_EXCLUSIVE_PASS=YES":"LEGACY_HERD_REPRODUCED=YES");return 0;
}

/* lockless_queue.c */
// FRONTIER-GH-0017: native aarch64 tagged-pointer ABA regression model.
// This is not presented as an upstream CPython source patch.
#define _GNU_SOURCE
#include <assert.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct node {
    struct node *next;
    unsigned value;
} node_t;

typedef struct __attribute__((aligned(16))) {
    node_t *ptr;
    uint64_t epoch;
} tagged_head_t;

typedef struct {
    tagged_head_t head;
    pthread_mutex_t gate_lock;
    pthread_cond_t gate_cv;
    int armed;
    int release;
    int stale_cas_rejected;
    node_t *worker_result;
} aba_fixture_t;

// ARMv8 exclusive doubleword-pair load/store gives a real lock-free 128-bit
// CAS on Cortex-A72: pointer + full 64-bit epoch are one atomic primitive.
static inline tagged_head_t atomic_load_tagged(tagged_head_t *head) {
    uint64_t ptr, epoch;
    __asm__ volatile(
        "ldaxp %x0, %x1, %2\n\t"
        "clrex"
        : "=&r"(ptr), "=&r"(epoch), "+Q"(*head)
        :
        : "memory");
    tagged_head_t out = {(node_t *)(uintptr_t)ptr, epoch};
    return out;
}

extern int atomic_cas_tagged_asm(tagged_head_t *head,
                                 tagged_head_t *expected,
                                 const tagged_head_t *desired);

static inline bool atomic_cas_tagged(tagged_head_t *head,
                                     tagged_head_t *expected,
                                     tagged_head_t desired) {
    return atomic_cas_tagged_asm(head, expected, &desired) == 1;
}

static void tagged_push(tagged_head_t *head, node_t *n) {
    tagged_head_t old = atomic_load_tagged(head);
    for (;;) {
        tagged_head_t desired = {n, old.epoch + 1};
        n->next = old.ptr;
        if (atomic_cas_tagged(head, &old, desired)) return;
    }
}

static void aba_gate_wait(aba_fixture_t *f) {
    pthread_mutex_lock(&f->gate_lock);
    f->armed = 1;
    pthread_cond_broadcast(&f->gate_cv);
    while (!f->release) pthread_cond_wait(&f->gate_cv, &f->gate_lock);
    pthread_mutex_unlock(&f->gate_lock);
}

static node_t *tagged_pop_gated(aba_fixture_t *f, bool use_epoch) {
    tagged_head_t old = atomic_load_tagged(&f->head);
    for (;;) {
        if (!old.ptr) return NULL;
        node_t *next = old.ptr->next;
        aba_gate_wait(f);
        // Legacy ignores the epoch; fixed CAS compares pointer AND epoch and
        // increments the generation on every successful head mutation.
        tagged_head_t desired = {next, use_epoch ? old.epoch + 1 : old.epoch};
        tagged_head_t expected = old;
        if (!use_epoch) expected.epoch = atomic_load_tagged(&f->head).epoch;
        if (atomic_cas_tagged(&f->head, &expected, desired)) return old.ptr;
        if (use_epoch) f->stale_cas_rejected++;
        old = expected;
    }
}

static void *aba_worker(void *arg, bool use_epoch) {
    aba_fixture_t *f = arg;
    f->worker_result = tagged_pop_gated(f, use_epoch);
    return NULL;
}

static void *legacy_worker(void *arg) { return aba_worker(arg, false); }
static void *fixed_worker(void *arg) { return aba_worker(arg, true); }

static void release_aba_worker(aba_fixture_t *f, pthread_t thread) {
    pthread_mutex_lock(&f->gate_lock);
    while (!f->armed) pthread_cond_wait(&f->gate_cv, &f->gate_lock);
    pthread_mutex_unlock(&f->gate_lock);
    // Recycle A after removing A and B while the worker holds A,B.
    node_t *a = f->head.ptr;
    tagged_head_t h = atomic_load_tagged(&f->head);
    tagged_head_t d = {a->next, h.epoch + 1};
    assert(atomic_cas_tagged(&f->head, &h, d));
    node_t *b = f->head.ptr;
    h = atomic_load_tagged(&f->head);
    d = (tagged_head_t){b->next, h.epoch + 1};
    assert(atomic_cas_tagged(&f->head, &h, d));
    tagged_push(&f->head, a);
    pthread_mutex_lock(&f->gate_lock);
    f->release = 1;
    pthread_cond_broadcast(&f->gate_cv);
    pthread_mutex_unlock(&f->gate_lock);
    pthread_join(thread, NULL);
    (void)b;
}

static int run_aba(bool fixed) {
    node_t a = {0}, b = {0};
    aba_fixture_t f;
    memset(&f, 0, sizeof(f));
    pthread_mutex_init(&f.gate_lock, NULL);
    pthread_cond_init(&f.gate_cv, NULL);
    tagged_push(&f.head, &b);
    tagged_push(&f.head, &a);
    pthread_t thread;
    assert(!pthread_create(&thread, NULL, fixed ? fixed_worker : legacy_worker, &f));
    release_aba_worker(&f, thread);
    bool legacy_aba = !fixed && f.worker_result == &a && f.head.ptr == &b;
    bool fixed_safe = fixed && f.worker_result == &a && f.head.ptr == NULL &&
                      f.stale_cas_rejected >= 1;
    printf("mode=%s worker=%s head=%s stale_cas_rejected=%d\n",
           fixed ? "fixed" : "legacy", f.worker_result == &a ? "A" : "other",
           f.head.ptr == &b ? "B(dangling)" : f.head.ptr == NULL ? "NULL" : "other",
           f.stale_cas_rejected);
    pthread_cond_destroy(&f.gate_cv);
    pthread_mutex_destroy(&f.gate_lock);
    if (fixed) {
        printf("TAGGED_EPOCH_ABA_REJECTED=%s\n", fixed_safe ? "YES" : "NO");
        return fixed_safe ? 0 : 2;
    }
    printf("LEGACY_ABA_REPRODUCED=%s\n", legacy_aba ? "YES" : "NO");
    return legacy_aba ? 0 : 3;
}

#define PRODUCERS 4
#define PER_PRODUCER 10000
#define TOTAL (PRODUCERS * PER_PRODUCER)
static tagged_head_t stress_head;
static node_t stress_nodes[TOTAL];
static atomic_uchar seen[TOTAL];
static atomic_int consumed;

static void *producer(void *arg) {
    unsigned p = (unsigned)(uintptr_t)arg;
    for (unsigned i = 0; i < PER_PRODUCER; i++) {
        unsigned id = p * PER_PRODUCER + i;
        stress_nodes[id].value = id;
        tagged_push(&stress_head, &stress_nodes[id]);
    }
    return NULL;
}

static void *consumer(void *arg) {
    (void)arg;
    for (;;) {
        tagged_head_t old = atomic_load_tagged(&stress_head);
        if (!old.ptr) {
            if (atomic_load_explicit(&consumed, memory_order_relaxed) == TOTAL) return NULL;
            sched_yield();
            continue;
        }
        tagged_head_t desired = {old.ptr->next, old.epoch + 1};
        if (!atomic_cas_tagged(&stress_head, &old, desired)) continue;
        unsigned id = old.ptr->value;
        if (id >= TOTAL || atomic_exchange_explicit(&seen[id], 1, memory_order_relaxed)) {
            fprintf(stderr, "duplicate/corrupt node id=%u\n", id);
            abort();
        }
        atomic_fetch_add_explicit(&consumed, 1, memory_order_relaxed);
    }
}

static int run_stress(void) {
    pthread_t producers[PRODUCERS], consumers[PRODUCERS];
    for (uintptr_t i = 0; i < PRODUCERS; i++)
        assert(!pthread_create(&producers[i], NULL, producer, (void *)i));
    for (unsigned i = 0; i < PRODUCERS; i++)
        assert(!pthread_create(&consumers[i], NULL, consumer, NULL));
    for (unsigned i = 0; i < PRODUCERS; i++) pthread_join(producers[i], NULL);
    for (unsigned i = 0; i < PRODUCERS; i++) pthread_join(consumers[i], NULL);
    int count = atomic_load(&consumed);
    bool pass = count == TOTAL && stress_head.ptr == NULL;
    for (unsigned i = 0; i < TOTAL; i++) pass &= atomic_load(&seen[i]) == 1;
    printf("stress_produced=%d stress_consumed=%d final_epoch=%llu duplicates=0\n",
           TOTAL, count, (unsigned long long)stress_head.epoch);
    printf("TAGGED_STRESS_PASS=%s\n", pass ? "YES" : "NO");
    return pass ? 0 : 4;
}

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "all";
    if (!strcmp(mode, "legacy")) return run_aba(false);
    if (!strcmp(mode, "fixed")) {
        int rc = run_aba(true);
        if (rc) return rc;
        return run_stress();
    }
    if (!strcmp(mode, "all")) {
        int a = run_aba(false), b = run_aba(true), c = b ? b : run_stress();
        return a || b || c;
    }
    fprintf(stderr, "usage: %s [legacy|fixed|all]\n", argv[0]);
    return 64;
}

/* tagged_cas_aarch64.S */
// Real ARMv8 128-bit tagged-head CAS: pointer + 64-bit epoch.
// bool atomic_cas_tagged_asm(head=x0, expected=x1, desired=x2)
// expected is refreshed on comparison failure, matching C11 CAS semantics.
.text
.align 2
.global atomic_cas_tagged_asm
.type atomic_cas_tagged_asm, %function
atomic_cas_tagged_asm:
    mov     x9, x0
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x2]
1:
    ldaxp   x7, x8, [x9]
    cmp     x7, x3
    ccmp    x8, x4, #0, eq
    b.ne    3f
    stlxp   w10, x5, x6, [x9]
    cbnz    w10, 1b
    mov     w0, #1
    ret
3:
    stp     x7, x8, [x1]
    clrex
    mov     w0, #0
    ret
.size atomic_cas_tagged_asm, .-atomic_cas_tagged_asm
.section .note.GNU-stack,"",@progbits

// FRONTIER-GH-0018: native cooperative-budget scheduler regression model.
// This is not presented as an upstream Tokio source patch.
use std::collections::VecDeque;
use std::env;
use std::sync::mpsc::{self, TryRecvError};
use std::thread;

const BUDGET: u32 = 128;
const GLOBAL_CHECK_INTERVAL: u64 = 64;

fn legacy() {
    let mut local: VecDeque<u64> = (0..1024).collect();
    let global = VecDeque::from([u64::MAX]);
    let mut local_polls = 0_u64;
    for _ in 0..4096 {
        // Legacy priority inversion: an always-nonempty local run queue is
        // polled forever and the global fallback is never checked.
        let task = local.pop_front().expect("local task");
        local.push_back(task);
        local_polls += 1;
    }
    assert_eq!(local_polls, 4096);
    assert_eq!(global.len(), 1);
    println!("LEGACY_STARVATION_REPRODUCED=YES local_polls={} global_completed=0 global_pending=1", local_polls);
}

fn fixed() {
    let mut local: VecDeque<u64> = (0..1024).collect();
    let mut global = VecDeque::from([u64::MAX]);
    let mut local_polls = 0_u64;
    let mut ticks = 0_u64;
    let mut budget_remaining = BUDGET;
    let mut global_checks = 0_u64;
    let mut first_global_tick = None;
    while global.len() == 1 {
        let task = local.pop_front().expect("local task");
        local.push_back(task);
        local_polls += 1;
        ticks += 1;
        budget_remaining -= 1;
        // A non-yielding local future still consumes cooperative budget. The
        // hard 64-tick fallback prevents a nonempty local queue starving global.
        if ticks % GLOBAL_CHECK_INTERVAL == 0 || budget_remaining == 0 {
            global_checks += 1;
            if global.pop_front().is_some() {
                first_global_tick = Some(ticks);
            }
            budget_remaining = BUDGET;
        }
    }
    assert_eq!(first_global_tick, Some(64));
    assert!(global_checks >= 1);
    println!("GLOBAL_FALLBACK_PASS=YES local_polls={} global_completed=1 first_global_tick=64 global_checks={} budget={} fallback_interval={}", local_polls, global_checks, BUDGET, GLOBAL_CHECK_INTERVAL);
}

fn stress() {
    const PRODUCERS: usize = 8;
    const PER_PRODUCER: usize = 10_000;
    const TOTAL: usize = PRODUCERS * PER_PRODUCER;
    let (tx, rx) = mpsc::channel::<usize>();
    let mut handles = Vec::new();
    for producer in 0..PRODUCERS {
        let sender = tx.clone();
        handles.push(thread::spawn(move || {
            for sequence in 0..PER_PRODUCER {
                sender.send(producer * PER_PRODUCER + sequence).expect("global send");
            }
        }));
    }
    drop(tx);
    let mut local: VecDeque<u64> = (0..256).collect();
    let mut ticks = 0_u64;
    let mut local_polls = 0_u64;
    let mut budget_remaining = BUDGET;
    let mut global_checks = 0_u64;
    let mut consumed = 0_usize;
    let mut sum = 0_usize;
    let expected_sum = (0..TOTAL).sum::<usize>();
    let mut last_check_tick = 0_u64;
    let mut max_ticks_between_global_checks = 0_u64;
    while consumed < TOTAL {
        let task = local.pop_front().expect("local task");
        local.push_back(task);
        local_polls += 1;
        ticks += 1;
        budget_remaining -= 1;
        if ticks % GLOBAL_CHECK_INTERVAL == 0 || budget_remaining == 0 {
            global_checks += 1;
            max_ticks_between_global_checks = max_ticks_between_global_checks.max(ticks - last_check_tick);
            last_check_tick = ticks;
            match rx.try_recv() {
                Ok(value) => {
                    consumed += 1;
                    sum += value;
                }
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    assert_eq!(consumed, TOTAL, "channel closed with work missing");
                }
            }
            budget_remaining = BUDGET;
        }
    }
    for handle in handles {
        handle.join().expect("producer join");
    }
    assert!(rx.try_recv().is_err());
    assert_eq!(sum, expected_sum);
    assert!(max_ticks_between_global_checks <= GLOBAL_CHECK_INTERVAL);
    println!("FIXED_STRESS_PASS=YES producers={} produced={} consumed={} checksum={} local_polls={} global_checks={} max_ticks_between_global_checks={} budget={}", PRODUCERS, TOTAL, consumed, sum, local_polls, global_checks, max_ticks_between_global_checks, BUDGET);
}

fn main() {
    match env::args().nth(1).as_deref() {
        Some("legacy") => legacy(),
        Some("fixed") => fixed(),
        Some("stress") => stress(),
        _ => {
            eprintln!("usage: worker legacy|fixed|stress");
            std::process::exit(2);
        }
    }
}

// FRONTIER-GH-0019 native regression model; not an upstream CPython patch.
// Models interpreter-list retirement versus daemon-thread tstate acquisition.
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    _Atomic int refs;
    _Atomic int retired;
    _Atomic int freed;
    _Atomic int phase;
    int observed_refs_after_retire;
} TState;

static pthread_mutex_t head_mutex = PTHREAD_MUTEX_INITIALIZER;

static void *legacy_deleter(void *arg) {
    TState *t = arg;
    while (atomic_load_explicit(&t->phase, memory_order_acquire) != 1) sched_yield();
    // Legacy defect: retire without head_mutex or a reference-lifetime barrier.
    atomic_store_explicit(&t->retired, 1, memory_order_release);
    atomic_store_explicit(&t->refs, 0, memory_order_release);
    atomic_store_explicit(&t->freed, 1, memory_order_release);
    atomic_store_explicit(&t->phase, 2, memory_order_release);
    return NULL;
}

static void *legacy_saver(void *arg) {
    TState *t = arg;
    // PyEval_SaveThread-like daemon acquisition has read the old tstate.
    atomic_store_explicit(&t->phase, 1, memory_order_release);
    while (atomic_load_explicit(&t->phase, memory_order_acquire) != 2) sched_yield();
    t->observed_refs_after_retire = atomic_fetch_add_explicit(&t->refs, 1, memory_order_acq_rel);
    return NULL;
}

static int legacy(void) {
    TState t = { .refs = 1 };
    pthread_t a, b;
    if (pthread_create(&a, NULL, legacy_deleter, &t) || pthread_create(&b, NULL, legacy_saver, &t)) return 2;
    pthread_join(a, NULL); pthread_join(b, NULL);
    int reproduced = atomic_load(&t.freed) && t.observed_refs_after_retire == 0 && atomic_load(&t.refs) == 1;
    printf("LEGACY_TSTATE_RACE_REPRODUCED=%s retired=%d old_refs=%d refs_after_invalid_acquire=%d\n",
           reproduced ? "YES" : "NO", atomic_load(&t.retired), t.observed_refs_after_retire, atomic_load(&t.refs));
    return reproduced ? 0 : 1;
}

typedef struct {
    TState *t;
    _Atomic int start;
    _Atomic int acquired;
    _Atomic int rejected;
    _Atomic int freed_count;
} FixedShared;

static void *fixed_saver(void *arg) {
    FixedShared *s = arg;
    while (!atomic_load_explicit(&s->start, memory_order_acquire)) sched_yield();
    int acquired = 0;
    pthread_mutex_lock(&head_mutex);
    if (!atomic_load_explicit(&s->t->retired, memory_order_relaxed)) {
        // List lock validates membership before atomic daemon-reference acquire.
        atomic_fetch_add_explicit(&s->t->refs, 1, memory_order_acq_rel);
        atomic_fetch_add_explicit(&s->acquired, 1, memory_order_relaxed);
        acquired = 1;
    } else {
        atomic_fetch_add_explicit(&s->rejected, 1, memory_order_relaxed);
    }
    pthread_mutex_unlock(&head_mutex);
    if (acquired) atomic_fetch_sub_explicit(&s->t->refs, 1, memory_order_acq_rel);
    return NULL;
}

static void *fixed_deleter(void *arg) {
    FixedShared *s = arg;
    while (!atomic_load_explicit(&s->start, memory_order_acquire)) sched_yield();
    pthread_mutex_lock(&head_mutex);
    atomic_store_explicit(&s->t->retired, 1, memory_order_relaxed);
    pthread_mutex_unlock(&head_mutex);
    atomic_fetch_sub_explicit(&s->t->refs, 1, memory_order_acq_rel); // drop interpreter-list ref
    while (atomic_load_explicit(&s->t->refs, memory_order_acquire) != 0) sched_yield();
    atomic_store_explicit(&s->t->freed, 1, memory_order_release);
    free(s->t); // real deallocation occurs only after every reference is gone
    atomic_fetch_add_explicit(&s->freed_count, 1, memory_order_relaxed);
    return NULL;
}

static int fixed(int iterations) {
    int total_acquired = 0, total_rejected = 0;
    for (int i = 0; i < iterations; ++i) {
        TState *t = calloc(1, sizeof(*t));
        if (!t) return 2;
        atomic_init(&t->refs, 1);
        FixedShared s = { .t = t };
        pthread_t a, b;
        if (pthread_create(&a, NULL, fixed_saver, &s) || pthread_create(&b, NULL, fixed_deleter, &s)) return 2;
        atomic_store_explicit(&s.start, 1, memory_order_release);
        pthread_join(a, NULL); pthread_join(b, NULL);
        if (atomic_load(&s.freed_count) != 1) return 1;
        total_acquired += atomic_load(&s.acquired);
        total_rejected += atomic_load(&s.rejected);
    }
    printf("FIXED_TSTATE_LIFETIME_PASS=YES iterations=%d acquired=%d rejected=%d freed=%d head_mutex=1 atomic_refcount=1\n",
           iterations, total_acquired, total_rejected, iterations);
    return 0;
}

