    if (argc == 2 && strcmp(argv[1], "fixed") == 0) return fixed(1);
    if (argc == 2 && strcmp(argv[1], "stress") == 0) return fixed(2000);
    fprintf(stderr, "usage: %s legacy|fixed|stress\n", argv[0]);
