typedef struct Node { struct Node *next; int id; } Node;
typedef struct __attribute__((aligned(16))) {
    Node *ptr;
    uint64_t epoch;
} TaggedHead;
_Static_assert(sizeof(TaggedHead) == 16, "pair CAS must be exactly 128 bits");
_Static_assert(sizeof(((TaggedHead *)0)->epoch) == 8, "epoch must be 64 bits");

/* Load a 128-bit head with acquire semantics using one exclusive pair load. */
static inline TaggedHead tagged_load_acquire(TaggedHead *addr) {
    uint64_t ptr, epoch;
    __asm__ volatile("ldaxp %0, %1, [%2]"
                     : "=&r"(ptr), "=&r"(epoch)
                     : "r"(addr)
                     : "memory");
    TaggedHead out = {.ptr = (Node *)(uintptr_t)ptr, .epoch = epoch};
    return out;
}

/*
 * Native aarch64 128-bit compare-and-swap.
 * LDAXP provides the acquire half; STLXP provides release and retries while
 * exclusive. A nonmatching pair exits without a store and returns the observed
 * head just like atomic_compare_exchange. No mutex or libatomic fallback.
 */
static inline bool tagged_cas(TaggedHead *addr, TaggedHead *expected,
                              TaggedHead desired) {
    uint64_t seen_ptr, seen_epoch;
    uint64_t expected_ptr = (uint64_t)(uintptr_t)expected->ptr;
    uint64_t expected_epoch = expected->epoch;
    uint64_t desired_ptr = (uint64_t)(uintptr_t)desired.ptr;
    uint64_t desired_epoch = desired.epoch;
    uint32_t status = 1;
    __asm__ volatile(
        "1:\n"
        "ldaxp %0, %1, [%3]\n"
        "cmp %0, %4\n"
        "ccmp %1, %5, #0, eq\n"
        "b.ne 2f\n"
        "stlxp %w2, %6, %7, [%3]\n"
        "cbnz %w2, 1b\n"
        "2:\n"
        : "=&r"(seen_ptr), "=&r"(seen_epoch), "+r"(status)
        : "r"(addr), "r"(expected_ptr), "r"(expected_epoch),
          "r"(desired_ptr), "r"(desired_epoch)
        : "memory", "cc");
    bool matched = seen_ptr == expected_ptr && s    cell_t *cell;
    for (;;) {
        cell = &q->cells[pos & (QUEUE_CAP - 1)];
        size_t seq = atomic_load_explicit(&cell->seq, memory_order_acquire);
        intptr_t dif = (intptr_t)seq - (intptr_t)(pos + 1);
        if (dif == 0) {
            if (atomic_compare_exchange_weak_explicit(&q->deq, &pos, pos + 1,
                    memory_order_relaxed, memory_order_relaxed)) break;
        } else if (dif < 0) {
            return false;
        } else {
            pos = atomic_load_explicit(&q->deq, memory_order_relaxed);
        }
    }
    *fd = cell->fd;
    atomic_store_explicit(&cell->seq, pos + QUEUE_CAP, memory_order_release);
    return true;
}

static void *consumer_main(void *opaque) {
    scenario_t *s = opaque;
    while (!atomic_load_explicit(&s->stop, memory_order_acquire) &&
           atomic_load_explicit(&s->consumed, memory_order_acquire) < CLIENTS) {
        int fd;
        if (!queue_pop(&s->queue, &fd)) { sched_yield(); continue; }
        char byte = 0;
        ssize_t n = read(fd, &byte, 1);
        if (n != 1 || byte != 'Z') atomic_fetch_add(&s->errors, 1);
        if (close(fd) != 0) atomic_fetch_add(&s->errors, 1);
        atomic_fetch_add_explicit(&s->consumed, 1, memory_order_release);
    }
    return NULL;
}

static void *accept_main(void *opaque) {
    accept_arg_t *arg = opaque;
    scenario_t *s = arg->s;
    int ep = epoll_create1(EPOLL_CLOEXEC);
    if (ep < 0) { atomic_fetch_add(&s->errors, 1); return NULL; }
    struct epoll_event reg = {.events = EPOLLIN | (s->exclusive ? EPOLLEXCLUSIVE : 0),
                              .data.u32 = (uint32_t)arg->index};
    if (epoll_ctl(ep, EPOLL_CTL_ADD, s->listen_fd, &reg) != 0) {
        atomic_fetch_add(&s->errors, 1); close(ep); return NULL;
    }
    while (!atomic_load_explicit(&s->stop, memory_order_acquire)) {
        struct epoll_event events[4];
        int n = epoll_wait(ep, events, 4, 10);
        if (n < 0) {
            if (errno == EINTR) continue;
            atomic_fetch_add(&s->errors, 1); break;
        }
        for (int i = 0; i < n; ++i) {
            s->wakeups[arg->index]++;
            bool accepted_this_wakeup = false;
            for (;;) {
                int fd = accept4(s->listen_fd, NULL, NULL, SOCK_CLOEXEC);
                if (fd >= 0) {
                    accepted_this_wakeup = true;
                    s->accepted_by[arg->index]++;
                    atomic_fetch_add_explicit(&s->accepted, 1, memory_order_release);
                    struct timeval tv = {.tv_sec = 2, .tv_usec = 0};
                    if (setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) != 0)
                        atomic_fetch_add(&s->errors, 1);
                    if (!queue_push(&s->queue, fd)) {
                        atomic_fetch_add(&s->errors, 1); close(fd);
                    }
                    continue;
                }
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    if (!accepted_this_wakeup) s->empty_wakeups[arg->index]++;
                    break;
                }
                if (errno == EINTR) continue;
                if (errno != EBADF && errno != EINVAL) atomic_fetch_add(&s->errors, 1);
                break;
            }
        }
    }
    close(ep);
    return NULL;
}

static int probe_reallocation_contract(void) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    int ep = epoll_create1(EPOLL_CLOEXEC);
    if (fd < 0 || ep < 0) return 1;
    struct epoll_event ev = {.events = EPOLLIN, .data.u64 = 1};
    if (epoll_ctl(ep, EPOLL_CTL_ADD, fd, &ev) != 0) return 2;
    ev.events = EPOLLIN | EPOLLEXCLUSIVE;
    errno = 0;
    int mod_rc = epoll_ctl(ep, EPOLL_CTL_MOD, fd, &ev);
    int mod_errno = errno;
    if (mod_rc != -1 || mod_errno != EINVAL) {
        fprintf(stderr, "EPOLLEXCLUSIVE MOD unexpectedly rc=%d errno=%d\n", mod_rc, mod_errno);
        return 3;
    }
    if (epoll_ctl(ep, EPOLL_CTL_DEL, fd, NULL) != 0) return 4;
    if (epoll_ctl(ep, EPOLL_CTL_ADD, fd, &ev) != 0) return 5;
    close(ep); close(fd);
    puts("REALLOC_MOD_EXCLUSIVE_REJECTED=YES errno=EINVAL DELETE_READD_EXCLUSIVE=PASS");
    return 0;
}

static int connect_and_send(uint16_t port_net) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (fd < 0) return 1;
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = port_net};
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0) { close(fd); return 2; }
    char byte = 'Z';
    if (write(fd, &byte, 1) != 1) { close(fd); return 3; }
    if (close(fd) != 0) return 4;
    return 0;
}

static int run_scenario(bool exclusive) {
    scenario_t s;
    memset(&s, 0, sizeof(s));
    s.exclusive = exclusive;
    atomic_init(&s.stop, 0); atomic_init(&s.accepted, 0);
    atomic_init(&s.consumed, 0); atomic_init(&s.errors, 0);
    queue_init(&s.queue);
    s.listen_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (s.listen_fd < 0) return 1;
    int one = 1;
    if (setsockopt(s.listen_fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one)) != 0 ||
        setsockopt(s.listen_fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one)) != 0) return 2;
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = 0};
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (bind(s.listen_fd, (struct sockaddr *)&addr, sizeof(addr)) != 0 ||
        listen(s.listen_fd, CLIENTS) != 0) return 3;
    socklen_t alen = sizeof(addr);
    if (getsockname(s.listen_fd, (struct sockaddr *)&addr, &alen) != 0) return 4;

    pthread_t consumers[CONSUMERS], accepters[ACCEPTERS];
    accept_arg_t args[ACCEPTERS];
    for (int i = 0; i < CONSUMERS; ++i)
        if (pthread_create(&consumers[i], NULL, consumer_main, &s) != 0) return 5;
    for (int i = 0; i < ACCEPTERS; ++i) {
        args[i] = (accept_arg_t){.s = &s, .index = i};
        if (pthread_create(&accepters[i], NULL, accept_main, &args[i]) != 0) return 6;
    }
    for (int i = 0; i < CLIENTS; ++i) {
        int rc = connect_and_send(addr.sin_port);
        if (rc != 0) { fprintf(stderr, "client %d rc=%d\n", i, rc); atomic_fetch_add(&s.errors, 1); }
    }
    int timed_out = 1;
    for (int i = 0; i < 20000; ++i) {
        if (atomic_load_explicit(&s.consumed, memory_order_acquire) == CLIENTS) { timed_out = 0; break; }
        struct timespec ts = {.tv_sec = 0, .tv_nsec = 1000000};
        nanosleep(&ts, NULL);
    }
    if (timed_out) atomic_fetch_add(&s.errors, 1);
    atomic_store_explicit(&s.stop, 1, memory_order_release);
    for (int i = 0; i < ACCEPTERS; ++i) pthread_join(accepters[i], NULL);
    for (int i = 0; i < CONSUMERS; ++i) pthread_join(consumers[i], NULL);
    close(s.listen_fd);

    int wakeups = 0, empty = 0, per_accept = 0;
    for (int i = 0; i < ACCEPTERS; ++i) {
        wakeups += s.wakeups[i]; empty += s.empty_wakeups[i]; per_accept += s.accepted_by[i];
    }
    int accepted = atomic_load(&s.accepted), consumed = atomic_load(&s.consumed);
    int errors = atomic_load(&s.errors);
    bool pass = !timed_out && errors == 0 && accepted == CLIENTS && consumed == CLIENTS && per_accept == CLIENTS;
    printf("%s flags=%#x clients=%d wakeups=%d empty_wakeups=%d accepted=%d consumed=%d errors=%d timeout=%d RESULT=%s\n",
           exclusive ? "FIXED_EPOLLEXCLUSIVE" : "LEGACY_NO_EXCLUSIVE",
           exclusive ? (unsigned)EPOLLEXCLUSIVE : 0U, CLIENTS, wakeups, empty,
           accepted, consumed, errors, timed_out, pass ? "PASS" : "FAIL");
    return pass ? 0 : 7;
}

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "all";
    if (!atomic_is_lock_free(&(fd_queue_t){0}.enq) || !atomic_is_lock_free(&(fd_queue_t){0}.deq)) {
        puts("LOCKFREE_SIZE_T=NO"); return 10;
    }
    puts("LOCKFREE_SIZE_T=YES queue=bounded_MPMC_mutex_free");
    if (strcmp(mode, "legacy") == 0) return run_scenario(false);
    if (probe_reallocation_contract() != 0) return 11;
    if (strcmp(mode, "fixed") == 0) return run_scenario(true);
    if (strcmp(mode, "all") != 0) return 12;
    int legacy = run_scenario(false);
    int fixed = run_scenario(true);
    if (legacy == 0 && fixed == 0) {
        printf("FRONTIER_GH_0020_PASS=YES clients_per_mode=%d note=legacy_empty_wakeups_are_measured_not_assumed\n", CLIENTS);
        return 0;
    }
    return 13;
}

// FRONTIER-GH-0026: native scheduler model, executed on aarch64.
// The legacy lane models an unyielding nested future pushed back at the local
// queue head without charging its cooperative budget. The fixed lane charges
// every local poll and checks the global queue at least once per 64 ticks.
use std::collections::VecDeque;
use std::env;

const COOPERATIVE_BUDGET: u32 = 128;
const GLOBAL_FALLBACK_TICKS: u64 = 64;

#[derive(Clone, Debug)]
enum Future {
    UnyieldingNested { id: u32 },
    GlobalCompletion { id: u32 },
}

struct Worker {
    local: VecDeque<Future>,
    global: VecDeque<Future>,
    ticks: u64,
    budget: u32,
    completed_global: Vec<u32>,
    first_global_tick: Option<u64>,
}

impl Worker {
    fn new(global_tasks: u32) -> Self {
        let local = (0..3).map(|id| Future::UnyieldingNested { id }).collect();
        let global = (0..global_tasks).map(|id| Future::GlobalCompletion { id }).collect();
        Self { local, global, ticks: 0, budget: COOPERATIVE_BUDGET,
               completed_global: Vec::new(), first_global_tick: None }
    }

    // Defect reproduction: no budget decrement and no global fallback.
    fn legacy_tick(&mut self) {
        self.ticks += 1;
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }

    // Fix: cooperative budget is charged for every local poll. A global check
    // occurs when the budget empties OR every 64 scheduler ticks, whichever
    // comes first. Unyielding work may continue only after that global check.
    fn fixed_tick(&mut self) {
        self.ticks += 1;
        if self.ticks % GLOBAL_FALLBACK_TICKS == 0 || self.budget == 0 {
            if let Some(Future::GlobalCompletion { id }) = self.global.pop_front() {
                self.completed_global.push(id);
                if self.first_global_tick.is_none() {
                    self.first_global_tick = Some(self.ticks);
                }
            }
            self.budget = COOPERATIVE_BUDGET;
            return;
        }
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.budget = self.budget.checked_sub(1).expect("budget underflow");
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }
}

fn legacy() {
    let mut w = Worker::new(1);
    for _ in 0..4096 { w.legacy_tick(); }
    assert_eq!(w.completed_global.len(), 0);
    assert_eq!(w.global.len(), 1);
    println!("LEGACY_UNYIELDING_STARVATION_REPRODUCED=YES ticks={} global_completed=0 local_queue_len={} budget_unchanged={}",
             w.ticks, w.local.len(), w.budget);
}

fn fixed() {
    let mut w = Worker::new(1);
    w.fixed_tick();
    let budget_after_first_poll = w.budget;
    while w.completed_global.is_empty() { w.fixed_tick(); }
    assert_eq!(budget_after_first_poll, 127);
    assert_eq!(w.first_global_tick, Some(64));
    assert_eq!(w.completed_global, vec![0]);
    println!("FIXED_COOPERATIVE_BUDGET=PASS budget_after_first_poll={}", budget_after_first_poll);
    println!("FIXED_GLOBAL_FALLBACK=PASS first_global_tick=64 interval_ticks=64 global_completed=1");
}

fn stress() {
    let mut w = Worker::new(64);
    for _ in 0..4096 { w.fixed_tick(); }
    assert_eq!(w.completed_global.len(), 64);
    assert!(w.global.is_empty());
    assert_eq!(w.local.len(), 3, "unyielding local futures remain pending");
    println!("FIXED_GLOBAL_STRESS=PASS ticks={} global_completed=64 first_global_tick={} local_pending=3",
             w.ticks, w.first_global_tick.unwrap());
}

fn main() {
    match env::args().nth(1).as_deref() {
        Some("legacy") => legacy(),
        Some("fixed") => fixed(),
        Some("stress") => stress(),
        _ => { eprintln!("usage: cooperative_budget_model legacy|fixed|stress"); std::process::exit(2); }
    }
}

// FRONTIER-GH-0027: deterministic native CPython-lifecycle race model.
// Scope: models the stated PyEval_SaveThread/PyInterpreterState_Delete hazard;
// it is not a claimed patch to CPython or torvalds/linux.
#define _POSIX_C_SOURCE 200809L
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct { _Atomic int refs; uint64_t magic; } TState;
typedef struct Interpreter { TState *tstate; bool deleting; struct Interpreter *next; } Interpreter;

static pthread_mutex_t head_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t gate_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t gate_cond = PTHREAD_COND_INITIALIZER;
static Interpreter *head;
static int gate_stage;
static int save_mutex_acquisitions;
static int delete_mutex_acquisitions;

static void wait_for_stage(int stage) {
    pthread_mutex_lock(&gate_mutex);
    while (gate_stage < stage) pthread_cond_wait(&gate_cond, &gate_mutex);
    pthread_mutex_unlock(&gate_mutex);
}
static void announce_save(void) {
    pthread_mutex_lock(&gate_mutex);
    gate_stage = 1;
    pthread_cond_broadcast(&gate_cond);
    pthread_mutex_unlock(&gate_mutex);
}
static void finish_delete(void) {
    pthread_mutex_lock(&gate_mutex);
    gate_stage = 2;
    pthread_cond_broadcast(&gate_cond);
    pthread_mutex_unlock(&gate_mutex);
}
static int release_tstate(TState *tstate) {
    int old = atomic_fetch_sub_explicit(&tstate->refs, 1, memory_order_acq_rel);
    // A dedicated mapping makes the buggy post-delete access a deterministic,
    // kernel-enforced UAF fault rather than allocator-dependent behavior.
    if (old == 1 && munmap(tstate, 4096) != 0) abort();
    return old;
}
static bool fixed_mode;
static void *save_thread(void *arg) {
    Interpreter *interp = arg;
    TState *tstate = NULL;
    if (fixed_mode) {
        // Fix: pin the interpreter/tstate while head_mutex protects the list.
        pthread_mutex_lock(&head_mutex);
        save_mutex_acquisitions++;
        if (!interp->deleting) {
            tstate = interp->tstate;
            int old = atomic_fetch_add_explicit(&tstate->refs, 1, memory_order_relaxed);
            if (old < 1) { pthread_mutex_unlock(&head_mutex); abort(); }
        }
        pthread_mutex_unlock(&head_mutex);
        if (!tstate) return NULL;
    } else {
        // Defect: an unpinned tstate pointer survives concurrent deletion.
        tstate = interp->tstate;
    }
    announce_save();
    wait_for_stage(2);
    if (!fixed_mode) {
        // Deliberate real UAF in buggy mode: deletion already unmapped this page.
        if (tstate->magic != UINT64_C(0x545354414745)) abort();
    }
    int old = release_tstate(tstate);
    if (fixed_mode && old != 1) abort();
    return NULL;
}
static void *delete_interpreter(void *arg) {
    Interpreter *interp = arg;
    wait_for_stage(1);
    if (fixed_mode) {
        // Fix: unlink/mark deleting and drop the owner ref under head_mutex.
        pthread_mutex_lock(&head_mutex);
        delete_mutex_acquisitions++;
        interp->deleting = true;
        if (head == interp) head = interp->next;
        int old = release_tstate(interp->tstate);
        if (old != 2) { pthread_mutex_unlock(&head_mutex); abort(); }
        pthread_mutex_unlock(&head_mutex);
    } else {
        // Defect: list mutation and owner release race with SaveThread.
        if (head == interp) head = interp->next;
        release_tstate(interp->tstate);
    }
    finish_delete();
    return NULL;
}
int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "--buggy") && strcmp(argv[1], "--fixed"))) return 64;
    fixed_mode = !strcmp(argv[1], "--fixed");
    Interpreter interp = {0};
    interp.tstate = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                         MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (interp.tstate == MAP_FAILED) return 70;
    atomic_init(&interp.tstate->refs, 1);
    interp.tstate->magic = UINT64_C(0x545354414745);
    head = &interp;
    pthread_t saver, deleter;
    if (pthread_create(&saver, NULL, save_thread, &interp)) return 71;
    if (pthread_create(&deleter, NULL, delete_interpreter, &interp)) return 72;
    pthread_join(saver, NULL);
    pthread_join(deleter, NULL);
    if (fixed_mode) {
        if (save_mutex_acquisitions != 1 || delete_mutex_acquisitions != 1 || head != NULL) return 73;
        puts("FIXED_OK: head_mutex protected save+delete; temporary ref pinned tstate; atomic decrements 2->1->0");
    } else {
        puts("BUGGY_RETURNED_WITHOUT_FAULT: reproduction did not fault");
        return 2;
    }
    return 0;
}

// FRONTIER-GH-0028: real Linux epoll/accept wakeup benchmark on aarch64.
// Uses one nonblocking SO_REUSEPORT listener registered in four independent
// epoll sets. Fixed mode enforces EPOLLEXCLUSIVE; accepted connections are
// assigned to lock-free atomic round-robin lanes. No mocked kernel behavior.
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <stdatomic.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define WORKERS 4
#define ROUNDS 100
static int listener;
static bool exclusive_mode;
static pthread_barrier_t start_barrier, finish_barrier;
static _Atomic int wakeups, accepts, would_block, lane_sequence;
static _Atomic int lane_counts[WORKERS];

static void *worker(void *arg) {
    intptr_t id = (intptr_t)arg;
    int ep = epoll_create1(EPOLL_CLOEXEC);
    if (ep < 0) abort();
    struct epoll_event reg = {.events = EPOLLIN | (exclusive_mode ? EPOLLEXCLUSIVE : 0), .data.u32 = (unsigned)id};
    if (epoll_ctl(ep, EPOLL_CTL_ADD, listener, &reg) != 0) { perror("epoll_ctl"); abort(); }
    pthread_barrier_wait(&start_barrier);
    for (int round = 0; round < ROUNDS; round++) {
        pthread_barrier_wait(&start_barrier);
        struct epoll_event event;
        int n = epoll_wait(ep, &event, 1, 50);
        if (n < 0 && errno != EINTR) abort();
        if (n > 0) {
            atomic_fetch_add_explicit(&wakeups, 1, memory_order_relaxed);
            int client = accept4(listener, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC);
            if (client >= 0) {
                atomic_fetch_add_explicit(&accepts, 1, memory_order_relaxed);
                // Lock-free queue distribution: one atomic ticket, no queue mutex.
                int lane = atomic_fetch_add_explicit(&lane_sequence, 1, memory_order_relaxed) % WORKERS;
                atomic_fetch_add_explicit(&lane_counts[lane], 1, memory_order_relaxed);
                close(client);
            } else if (errno == EAGAIN || errno == EWOULDBLOCK) {
                atomic_fetch_add_explicit(&would_block, 1, memory_order_relaxed);
            } else { perror("accept4"); abort(); }
        }
        pthread_barrier_wait(&finish_barrier);
    }
    close(ep);
    return NULL;
}
static int make_client(void) {
