// FRONTIER-GH-0029: deterministic two-thread ABA reproduction on aarch64.
// The fixed queue uses a pointer+64-bit epoch pair with real ARMv8 LDAXP/STLXP
// double-width CAS (acquire/release), not an emulated mutex or mock atomic.
#define _POSIX_C_SOURCE 200809L
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node { struct Node *next; int id; } Node;
typedef struct Head { Node *ptr; uint64_t epoch; } Head;
static _Atomic(Node *) legacy_head;
static Head tagged_head;
static Node a, b;
static bool fixed_mode;
static pthread_mutex_t gate_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t gate_cond = PTHREAD_COND_INITIALIZER;
static int stage;

static void set_stage(int value) {
    pthread_mutex_lock(&gate_mutex); stage = value;
    pthread_cond_broadcast(&gate_cond); pthread_mutex_unlock(&gate_mutex);
}
static void wait_stage(int value) {
    pthread_mutex_lock(&gate_mutex);
    while (stage < value) pthread_cond_wait(&gate_cond, &gate_mutex);
    pthread_mutex_unlock(&gate_mutex);
}
__attribute__((noinline)) static bool tagged_cas(Head *expected, Head desired) {
    uint64_t old_ptr, old_epoch, status;
    do {
        // 128-bit exclusivity granule: pointer and epoch change atomically.
        __asm__ volatile("ldaxp %0,%1,[%2]"
                         : "=&r"(old_ptr), "=&r"(old_epoch)
                         : "r"(&tagged_head) : "memory");
        if (old_ptr != (uint64_t)expected->ptr || old_epoch != expected->epoch) {
            __asm__ volatile("clrex" ::: "memory");
            expected->ptr = (Node *)old_ptr; expected->epoch = old_epoch;
            return false;
        }
        __asm__ volatile("stlxp %w0,%1,%2,[%3]"
                         : "=&r"(status)
                         : "r"((uint64_t)desired.ptr), "r"(desired.epoch), "r"(&tagged_head)
                         : "memory");
    } while (status != 0);
    return true;
}
static void tagged_push(Node *node) {
    Head observed = tagged_head, desired;
    do { node->next = observed.ptr; desired = (Head){node, observed.epoch + 1}; }
    while (!tagged_cas(&observed, desired));
}
static Node *tagged_pop(void) {
    Head observed = tagged_head, desired;
    do { if (!observed.ptr) return NULL; desired = (Head){observed.ptr->next, observed.epoch + 1}; }
    while (!tagged_cas(&observed, desired));
    return observed.ptr;
}
static Node *legacy_pop(void) {
    Node *observed = atomic_load_explicit(&legacy_head, memory_order_acquire);
    while (observed && !atomic_compare_exchange_weak_explicit(&legacy_head, &observed,
            observed->next, memory_order_acq_rel, memory_order_acquire)) {}
    return observed;
}
static void *preempted_pop(void *unused) {
    (void)unused;
    if (fixed_mode) {
        Head expected = tagged_head;
        Node *next = expected.ptr->next;
        set_stage(1); wait_stage(2);
        Head desired = {next, expected.epoch + 1};
        bool accepted = tagged_cas(&expected, desired);
        printf("FIXED_ABA_REJECTED=%s observed_epoch=%llu current_epoch=%llu head_id=%d\n",
               accepted ? "NO" : "YES", (unsigned long long)expected.epoch,
               (unsigned long long)tagged_head.epoch,
               tagged_head.ptr ? tagged_head.ptr->id : -1);
        if (accepted) abort();
    } else {
        Node *expected = atomic_load_explicit(&legacy_head, memory_order_acquire);
        Node *next = expected->next;
        set_stage(1); wait_stage(2);
        bool accepted = atomic_compare_exchange_strong_explicit(&legacy_head, &expected,
                        next, memory_order_acq_rel, memory_order_acquire);
        Node *head = atomic_load_explicit(&legacy_head, memory_order_acquire);
        printf("LEGACY_ABA_ACCEPTED=%s head_id=%d expected_recycled_id=1\n",
               accepted ? "YES" : "NO", head ? head->id : -1);
        if (!accepted || head != &b) abort();
    }
    return NULL;
}
int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "--legacy") && strcmp(argv[1], "--fixed"))) return 64;
    fixed_mode = !strcmp(argv[1], "--fixed");
    a = (Node){&b, 1}; b = (Node){NULL, 2};
    atomic_init(&legacy_head, &a); tagged_head = (Head){&a, 0};
    pthread_t thread;
    if (pthread_create(&thread, NULL, preempted_pop, NULL)) return 70;
    wait_stage(1);
    if (fixed_mode) {
        // A -> B -> empty -> A: address A recycles, but epoch becomes 3.
        if (tagged_pop() != &a || tagged_pop() != &b) abort();
        tagged_push(&a);
    } else {
        // Same ABA sequence with an untagged pointer CAS.
        if (legacy_pop() != &a || legacy_pop() != &b) abort();
        a.next = NULL;
        atomic_store_explicit(&legacy_head, &a, memory_order_release);
    }
    set_stage(2);
    pthread_join(thread, NULL);
    if (fixed_mode && (tagged_head.ptr != &a || tagged_head.epoch != 3)) abort();
    return 0;
}

// FRONTIER-GH-0030: native scheduler model, executed on aarch64.
// The legacy lane models an unyielding nested future pushed back at the local
// queue head without charging its cooperative budget. The fixed lane charges
// every local poll and checks the global queue at least once per 64 ticks.
use std::collections::VecDeque;
use std::env;

const COOPERATIVE_BUDGET: u32 = 128;
const GLOBAL_FALLBACK_TICKS: u64 = 64;

#[derive(Clone, Debug)]
enum Future {
    UnyieldingNested { id: u32 },
    GlobalCompletion { id: u32 },
}

struct Worker {
    local: VecDeque<Future>,
    global: VecDeque<Future>,
    ticks: u64,
    budget: u32,
    completed_global: Vec<u32>,
    first_global_tick: Option<u64>,
}

impl Worker {
    fn new(global_tasks: u32) -> Self {
        let local = (0..3).map(|id| Future::UnyieldingNested { id }).collect();
        let global = (0..global_tasks).map(|id| Future::GlobalCompletion { id }).collect();
        Self { local, global, ticks: 0, budget: COOPERATIVE_BUDGET,
               completed_global: Vec::new(), first_global_tick: None }
    }

    // Defect reproduction: no budget decrement and no global fallback.
    fn legacy_tick(&mut self) {
        self.ticks += 1;
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }

    // Fix: cooperative budget is charged for every local poll. A global check
    // occurs when the budget empties OR every 64 scheduler ticks, whichever
    // comes first. Unyielding work may continue only after that global check.
    fn fixed_tick(&mut self) {
        self.ticks += 1;
        if self.ticks % GLOBAL_FALLBACK_TICKS == 0 || self.budget == 0 {
            if let Some(Future::GlobalCompletion { id }) = self.global.pop_front() {
                self.completed_global.push(id);
                if self.first_global_tick.is_none() {
                    self.first_global_tick = Some(self.ticks);
                }
            }
            self.budget = COOPERATIVE_BUDGET;
            return;
        }
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.budget = self.budget.checked_sub(1).expect("budget underflow");
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }
}

fn legacy() {
    let mut w = Worker::new(1);
    for _ in 0..4096 { w.legacy_tick(); }
    assert_eq!(w.completed_global.len(), 0);
    assert_eq!(w.global.len(), 1);
    println!("LEGACY_UNYIELDING_STARVATION_REPRODUCED=YES ticks={} global_completed=0 local_queue_len={} budget_unchanged={}",
             w.ticks, w.local.len(), w.budget);
}

fn fixed() {
    let mut w = Worker::new(1);
    w.fixed_tick();
    let budget_after_first_poll = w.budget;
    while w.completed_global.is_empty() { w.fixed_tick(); }
    assert_eq!(budget_after_first_poll, 127);
    assert_eq!(w.first_global_tick, Some(64));
    assert_eq!(w.completed_global, vec![0]);
    println!("FIXED_COOPERATIVE_BUDGET=PASS budget_after_first_poll={}", budget_after_first_poll);
    println!("FIXED_GLOBAL_FALLBACK=PASS first_global_tick=64 interval_ticks=64 global_completed=1");
}

fn stress() {
    let mut w = Worker::new(64);
    for _ in 0..4096 { w.fixed_tick(); }
    assert_eq!(w.completed_global.len(), 64);
    assert!(w.global.is_empty());
    assert_eq!(w.local.len(), 3, "unyielding local futures remain pending");
    println!("FIXED_GLOBAL_STRESS=PASS ticks={} global_completed=64 first_global_tick={} local_pending=3",
             w.ticks, w.first_global_tick.unwrap());
}

fn main() {
    match env::args().nth(1).as_deref() {
        Some("legacy") => legacy(),
        Some("fixed") => fixed(),
        Some("stress") => stress(),
        _ => { eprintln!("usage: cooperative_budget_model legacy|fixed|stress"); std::process::exit(2); }
    }
}

// FRONTIER-GH-0031: deterministic native CPython subinterpreter lifetime model.
// Negative control: deletion wins before a daemon thread's PyEval_SaveThread.
// Fixed lane: head_mutex serializes interpreter-list deletion with tstate
// acquisition; atomic acquire/release refcount keeps tstate alive until the
// daemon releases the GIL. The negative control detects poison before access,
// avoiding an intentional C undefined-behaviour read in the test process.
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TState {
    atomic_int refs;
    int freed;
    unsigned canary;
} TState;

typedef struct Shared {
    pthread_mutex_t head_mutex;
    pthread_cond_t cv;
    TState *head;
    TState *tstate;
    int stage;
    int daemon_observed_uaf;
    int daemon_completed;
} Shared;

static void init_shared(Shared *s) {
    memset(s, 0, sizeof(*s));
    pthread_mutex_init(&s->head_mutex, NULL);
    pthread_cond_init(&s->cv, NULL);
    s->tstate = calloc(1, sizeof(*s->tstate));
    if (!s->tstate) abort();
    atomic_init(&s->tstate->refs, 1); // interpreter owner's reference
    s->tstate->canary = 0xC0FFEE;
    s->head = s->tstate;
}

static void destroy_shared(Shared *s) {
    free(s->tstate);
    pthread_cond_destroy(&s->cv);
    pthread_mutex_destroy(&s->head_mutex);
}

static void *legacy_daemon(void *arg) {
    Shared *s = arg;
    TState *raw = s->tstate; // unlocked acquisition: defect under test
    pthread_mutex_lock(&s->head_mutex);
    s->stage = 1; // daemon is suspended immediately before SaveThread
    pthread_cond_broadcast(&s->cv);
    while (s->stage < 2) pthread_cond_wait(&s->cv, &s->head_mutex);
    // Poison is checked before any simulated dereference, so the test itself
    // remains defined while still proving that deletion won the lifetime race.
    if (raw->freed) s->daemon_observed_uaf = 1;
    pthread_mutex_unlock(&s->head_mutex);
    return NULL;
}

static int legacy_once(void) {
    Shared s;
    init_shared(&s);
    pthread_t daemon;
    if (pthread_create(&daemon, NULL, legacy_daemon, &s)) return 2;
    pthread_mutex_lock(&s.head_mutex);
    while (s.stage < 1) pthread_cond_wait(&s.cv, &s.head_mutex);
    // Models PyInterpreterState_Delete without head_mutex/list lifetime safety:
    // unlink and poison tstate while the daemon retains its raw pointer.
    s.head = NULL;
    s.tstate->freed = 1;
    atomic_store_explicit(&s.tstate->refs, 0, memory_order_release);
    s.stage = 2;
    pthread_cond_broadcast(&s.cv);
    pthread_mutex_unlock(&s.head_mutex);
    pthread_join(daemon, NULL);
    int reproduced = s.daemon_observed_uaf && atomic_load(&s.tstate->refs) == 0;
    destroy_shared(&s);
    return reproduced ? 0 : 1;
}

static void *fixed_daemon(void *arg) {
    Shared *s = arg;
    pthread_mutex_lock(&s->head_mutex);
    // Acquire head_mutex before touching the interpreter list or tstate refs.
    if (s->head == s->tstate && !s->tstate->freed) {
        atomic_fetch_add_explicit(&s->tstate->refs, 1, memory_order_acquire);
        s->stage = 1; // daemon reference is now independently owned
        pthread_cond_broadcast(&s->cv);
    }
    while (s->stage < 2) pthread_cond_wait(&s->cv, &s->head_mutex);
    pthread_mutex_unlock(&s->head_mutex);

    // Simulated PyEval_SaveThread/GIL release occurs without head_mutex while
    // the atomic daemon reference keeps the object alive.
    if (!s->tstate->freed && s->tstate->canary == 0xC0FFEE)
        s->daemon_completed = 1;
    int old = atomic_fetch_sub_explicit(&s->tstate->refs, 1, memory_order_acq_rel);
    if (old == 2) s->daemon_completed = s->daemon_completed && 1;
    return NULL;
}

static int fixed_once(int *owner_old, int *remaining) {
    Shared s;
    init_shared(&s);
    pthread_t daemon;
    if (pthread_create(&daemon, NULL, fixed_daemon, &s)) return 2;
    pthread_mutex_lock(&s.head_mutex);
    while (s.stage < 1) pthread_cond_wait(&s.cv, &s.head_mutex);
    // Deletion and list unlink are serialized by head_mutex. Drop only the
    // owner's reference; the daemon's atomic reference prevents premature free.
    s.head = NULL;
    *owner_old = atomic_fetch_sub_explicit(&s.tstate->refs, 1, memory_order_acq_rel);
    s.stage = 2;
    pthread_cond_broadcast(&s.cv);
    pthread_mutex_unlock(&s.head_mutex);
    pthread_join(daemon, NULL);
    *remaining = atomic_load_explicit(&s.tstate->refs, memory_order_acquire);
    int ok = *owner_old == 2 && *remaining == 0 && s.daemon_completed &&
             !s.daemon_observed_uaf && !s.tstate->freed;
    destroy_shared(&s);
    return ok ? 0 : 1;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: subinterpreter_lifetime legacy|fixed|stress\n");
        return 2;
    }
    if (!strcmp(argv[1], "legacy")) {
        if (legacy_once()) return 1;
        puts("LEGACY_GIL_DELETE_UAF_REPRODUCED=YES owner_refcount=0 daemon_observed_freed=1");
        return 0;
    }
    int owner_old = 0, remaining = -1;
    if (!strcmp(argv[1], "fixed")) {
        if (fixed_once(&owner_old, &remaining)) return 1;
        puts("FIXED_HEAD_MUTEX=PASS interpreter_unlink_serialized=1");
        printf("FIXED_TSTATE_REFCOUNT=PASS owner_decrement_old=%d final_refs=%d\n", owner_old, remaining);
        puts("FIXED_NO_UAF=PASS daemon_gil_release_completed=1 freed_before_daemon=0");
        return 0;
    }
    if (!strcmp(argv[1], "stress")) {
        for (int i = 0; i < 1000; ++i) {
            if (fixed_once(&owner_old, &remaining)) {
                fprintf(stderr, "fixed stress failed at iteration %d\n", i);
                return 1;
            }
        }
        puts("FIXED_LIFETIME_STRESS=PASS iterations=1000 final_refs=0 uaf=0");
        return 0;
    }
    return 2;
}

// FRONTIER-GH-0032: real Linux loopback epoll thundering-herd regression.
// Four epoll instances share one SO_REUSEPORT listening socket. The negative
// control registers without EPOLLEXCLUSIVE; the fixed lane requires that flag
// and distributes every accepted descriptor with an atomic lock-free ticket.
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define WORKERS 4
#define ROUNDS 128

typedef struct {
    int listen_fd;
    int exclusive;
    pthread_barrier_t start;
    pthread_barrier_t done;
    atomic_uint ticket;
} Server;

typedef struct {
    Server *server;
    int epoll_fd;
    int wakeups;
    int accepted;
    int ewouldblock;
    int assigned[WORKERS];
} Worker;

static void die(const char *what) { perror(what); exit(2); }

static int nonblock(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0) return -1;
    return 0;
}

static int make_listener(uint16_t *port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (fd < 0) die("socket");
    int one = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one)) ||
        setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one)))
        die("setsockopt SO_REUSEPORT");
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = 0;
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr))) die("bind");
    if (listen(fd, 128)) die("listen");
    socklen_t len = sizeof(addr);
    if (getsockname(fd, (struct sockaddr *)&addr, &len)) die("getsockname");
    *port = ntohs(addr.sin_port);
    if (nonblock(fd)) die("listen O_NONBLOCK");
    return fd;
}

static void *worker_main(void *arg) {
    Worker *w = arg;
    Server *s = w->server;
    struct epoll_event event;
    for (int round = 0; round < ROUNDS; ++round) {
        pthread_barrier_wait(&s->start);
        int n;
        do { n = epoll_wait(w->epoll_fd, &event, 1, 25); }
        while (n < 0 && errno == EINTR);
        if (n < 0) die("epoll_wait");
        if (n == 1) {
            ++w->wakeups;
            int accepted_this_wakeup = 0;
            for (;;) {
                int fd = accept4(s->listen_fd, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC);
                if (fd >= 0) {
                    ++w->accepted;
                    ++accepted_this_wakeup;
                    // Lock-free socket queue distribution: exactly one atomic
                    // ticket owns each accepted fd and selects its destination.
                    unsigned owner = atomic_fetch_add_explicit(&s->ticket, 1, memory_order_relaxed) % WORKERS;
                    ++w->assigned[owner];
                    close(fd);
                    continue;
                }
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    if (accepted_this_wakeup == 0) ++w->ewouldblock;
                    break;
                }
                if (errno == EINTR) continue;
                die("accept4");
            }
        }
        pthread_barrier_wait(&s->done);
    }
    return NULL;
}

static void one_connection(uint16_t port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (fd < 0) die("client socket");
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(port);
    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr))) die("connect");
    char byte = 'x';
    if (write(fd, &byte, 1) != 1) die("client write");
    close(fd);
}

static Worker *run_lane(int exclusive, Server *server_out, pthread_t **threads_out) {
    uint16_t port;
    Server *s = server_out;
    memset(s, 0, sizeof(*s));
    s->exclusive = exclusive;
    s->listen_fd = make_listener(&port);
    atomic_init(&s->ticket, 0);
    if (pthread_barrier_init(&s->start, NULL, WORKERS + 1) ||
        pthread_barrier_init(&s->done, NULL, WORKERS + 1)) die("barrier init");
    Worker *workers = calloc(WORKERS, sizeof(*workers));
    pthread_t *threads = calloc(WORKERS, sizeof(*threads));
    if (!workers || !threads) die("calloc");
    for (int i = 0; i < WORKERS; ++i) {
        workers[i].server = s;
        workers[i].epoll_fd = epoll_create1(EPOLL_CLOEXEC);
        if (workers[i].epoll_fd < 0) die("epoll_create1");
        struct epoll_event event = {0};
        event.events = EPOLLIN;
        if (exclusive) event.events |= EPOLLEXCLUSIVE; // mandatory, never ignored
        event.data.fd = s->listen_fd;
        if (epoll_ctl(workers[i].epoll_fd, EPOLL_CTL_ADD, s->listen_fd, &event))
            die(exclusive ? "EPOLLEXCLUSIVE registration required" : "legacy epoll registration");
        if (pthread_create(&threads[i], NULL, worker_main, &workers[i])) die("pthread_create");
    }
    for (int round = 0; round < ROUNDS; ++round) {
        pthread_barrier_wait(&s->start);
        usleep(1000); // let every worker enter epoll_wait before one connection
        one_connection(port);
        pthread_barrier_wait(&s->done);
    }
    for (int i = 0; i < WORKERS; ++i) {
        pthread_join(threads[i], NULL);
        close(workers[i].epoll_fd);
    }
    close(s->listen_fd);
    *threads_out = threads;
    return workers;
}

static void summarize(const char *lane, Worker *workers, Server *s, pthread_t *threads) {
    int wakeups = 0, accepted = 0, ewouldblock = 0;
    unsigned assigned[WORKERS] = {0};
    for (int i = 0; i < WORKERS; ++i) {
        wakeups += workers[i].wakeups;
        accepted += workers[i].accepted;
        ewouldblock += workers[i].ewouldblock;
        for (int j = 0; j < WORKERS; ++j) assigned[j] += workers[i].assigned[j];
    }
    if (accepted != ROUNDS || (unsigned)accepted != atomic_load(&s->ticket)) {
        fprintf(stderr, "%s distribution mismatch accepted=%d ticket=%u\n", lane, accepted, atomic_load(&s->ticket));
        exit(1);
    }
    printf("%s rounds=%d wakeups=%d accepted=%d spurious_ewouldblock=%d exclusive=%d assigned=[%u,%u,%u,%u]\n",
           lane, ROUNDS, wakeups, accepted, ewouldblock, s->exclusive,
           assigned[0], assigned[1], assigned[2], assigned[3]);
    free(workers);
    free(threads);
    pthread_barrier_destroy(&s->start);
    pthread_barrier_destroy(&s->done);
}

int main(void) {
    Server legacy_server, fixed_server;
    pthread_t *legacy_threads, *fixed_threads;
    Worker *legacy = run_lane(0, &legacy_server, &legacy_threads);
    Worker *fixed = run_lane(1, &fixed_server, &fixed_threads);
    int legacy_wakeups = 0, fixed_wakeups = 0;
    for (int i = 0; i < WORKERS; ++i) {
        legacy_wakeups += legacy[i].wakeups;
        fixed_wakeups += fixed[i].wakeups;
    }
    if (legacy_wakeups <= fixed_wakeups) {
        fprintf(stderr, "no measurable herd reduction: legacy=%d fixed=%d\n", legacy_wakeups, fixed_wakeups);
        return 1;
    }
    summarize("LEGACY_EPOLL_HERD", legacy, &legacy_server, legacy_threads);
    summarize("FIXED_EPOLLEXCLUSIVE", fixed, &fixed_server, fixed_threads);
    printf("EPOLLEXCLUSIVE_HERD_REDUCTION=PASS legacy_wakeups=%d fixed_wakeups=%d lockfree_ticket_distribution=PASS\n",
           legacy_wakeups, fixed_wakeups);
    return 0;
}

// FRONTIER-GH-0033: deterministic two-thread ABA regression on physical aarch64.
// The legacy lane recycles A->B->C back to A->C while a consumer holds A/B.
// The fixed lane couples the pointer to a uint64_t epoch in one 16-byte atomic CAS.
#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct Node Node;
struct Node { int id; _Atomic(Node *) next; };
typedef struct { Node *ptr; uint64_t epoch; } Tagged;
typedef struct {
    int fixed, rounds;
    Node a, b, c;
    _Atomic(Node *) plain_head;
    Tagged tagged_head;
    _Atomic int stage;
    long aba, rejected, chain_ok;
} Harness;

static void stage_store(Harness *h, int s) { atomic_store_explicit(&h->stage, s, memory_order_release); }
static void stage_wait(Harness *h, int s) { while (atomic_load_explicit(&h->stage, memory_order_acquire) != s) sched_yield(); }

static int tagged_cas(Tagged *head, Tagged *expected, Node *desired) {
    Tagged want = { desired, expected->epoch + 1 }; // 64-bit generation changes on every successful update.
    return __atomic_compare_exchange(head, expected, &want, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE);
}
static Node *tagged_pop(Tagged *head) {
    Tagged old = ({ Tagged old; __atomic_load(head, &old, __ATOMIC_ACQUIRE); old; });
    for (;;) {
        if (!old.ptr) return NULL;
        Node *next = atomic_load_explicit(&old.ptr->next, memory_order_acquire);
        Tagged expected = old;
        if (tagged_cas(head, &expected, next)) return old.ptr;
        old = expected;
    }
}
static void tagged_push(Tagged *head, Node *n) {
    Tagged old = ({ Tagged old; __atomic_load(head, &old, __ATOMIC_ACQUIRE); old; });
    for (;;) {
        atomic_store_explicit(&n->next, old.ptr, memory_order_relaxed);
        Tagged expected = old;
        if (tagged_cas(head, &expected, n)) return;
        old = expected;
    }
}
static Node *plain_pop(_Atomic(Node *) *head) {
    Node *old = atomic_load_explicit(head, memory_order_acquire);
    while (old) {
        Node *next = atomic_load_explicit(&old->next, memory_order_acquire);
        if (atomic_compare_exchange_weak_explicit(head, &old, next, memory_order_acq_rel, memory_order_acquire)) return old;
    }
    return NULL;
}
static void plain_push(_Atomic(Node *) *head, Node *n) {
    Node *old = atomic_load_explicit(head, memory_order_acquire);
    for (;;) {
        atomic_store_explicit(&n->next, old, memory_order_relaxed);
        if (atomic_compare_exchange_weak_explicit(head, &old, n, memory_order_acq_rel, memory_order_acquire)) return;
    }
}
static void init_round(Harness *h, int r) {
    atomic_store(&h->a.next, &h->b); atomic_store(&h->b.next, &h->c); atomic_store(&h->c.next, NULL);
    if (h->fixed) { Tagged t = { &h->a, ((uint64_t)r + 1) << 32 }; __atomic_store(&h->tagged_head, &t, __ATOMIC_RELEASE); }
    else atomic_store_explicit(&h->plain_head, &h->a, memory_order_release);
}
static void *victim(void *arg) {
    Harness *h = arg;
    for (int r = 0; r < h->rounds; r++) {
        stage_wait(h, 1);
        if (h->fixed) {
            Tagged old = ({ Tagged old; __atomic_load(&h->tagged_head, &old, __ATOMIC_ACQUIRE); old; });
            Node *next = atomic_load_explicit(&old.ptr->next, memory_order_acquire);
            stage_store(h, 2); stage_wait(h, 3);
            Tagged expected = old;
            if (!tagged_cas(&h->tagged_head, &expected, next)) h->rejected++; else h->aba++;
        } else {
            Node *old = atomic_load_explicit(&h->plain_head, memory_order_acquire);
            Node *next = atomic_load_explicit(&old->next, memory_order_acquire);
            stage_store(h, 2); stage_wait(h, 3);
            Node *expected = old;
            if (atomic_compare_exchange_strong_explicit(&h->plain_head, &expected, next, memory_order_acq_rel, memory_order_acquire)) h->aba++;
        }
        stage_store(h, 4);
    }
    return NULL;
}
static void *recycler(void *arg) {
    Harness *h = arg;
    for (int r = 0; r < h->rounds; r++) {
        init_round(h, r); stage_store(h, 1); stage_wait(h, 2);
        if (h->fixed) {
            Node *a = tagged_pop(&h->tagged_head), *b = tagged_pop(&h->tagged_head);
            if (a != &h->a || b != &h->b) abort();
            tagged_push(&h->tagged_head, a); // Recycle identical address A with a different epoch.
        } else {
            Node *a = plain_pop(&h->plain_head), *b = plain_pop(&h->plain_head);
            if (a != &h->a || b != &h->b) abort();
            plain_push(&h->plain_head, a);
        }
        stage_store(h, 3); stage_wait(h, 4);
        if (h->fixed) {
            Tagged t = ({ Tagged old; __atomic_load(&h->tagged_head, &old, __ATOMIC_ACQUIRE); old; });
            if (t.ptr == &h->a && atomic_load(&h->a.next) == &h->c && atomic_load(&h->c.next) == NULL) h->chain_ok++;
        }
    }
    stage_store(h, 5); return NULL;
}
static Harness run_lane(int fixed, int rounds) {
    Harness h; memset(&h, 0, sizeof(h)); h.fixed = fixed; h.rounds = rounds;
    h.a.id = 1; h.b.id = 2; h.c.id = 3;
    pthread_t v, r;
    if (pthread_create(&v, NULL, victim, &h) || pthread_create(&r, NULL, recycler, &h)) abort();
    pthread_join(v, NULL); pthread_join(r, NULL); return h;
}
static int ordered_regression(void) {
    Tagged head = {0}; Node n[3];
    for (int i = 0; i < 3; i++) { n[i].id = i; atomic_init(&n[i].next, NULL); tagged_push(&head, &n[i]); }
    for (int i = 2; i >= 0; i--) if (tagged_pop(&head) != &n[i]) return 0;
    return head.ptr == NULL && head.epoch == 6;
}
int main(void) {
    const int rounds = 2000;
    Harness legacy = run_lane(0, rounds), fixed = run_lane(1, rounds);
    int ordered = ordered_regression();
    printf("LEGACY_POINTER_CAS rounds=%d ABA_success=%ld corrupted_head_B=%ld\n", rounds, legacy.aba, legacy.aba);
    printf("FIXED_TAGGED_CAS rounds=%d ABA_success=%ld stale_CAS_rejected=%ld intact_A_to_C=%ld epoch_bits=64\n", rounds, fixed.aba, fixed.rejected, fixed.chain_ok);
    printf("ORDERED_PUSH_POP=%s tagged_16B_always_lockfree=%d\n", ordered ? "PASS" : "FAIL", __atomic_always_lock_free(sizeof(Tagged), 0));
    if (legacy.aba != rounds || fixed.aba != 0 || fixed.rejected != rounds || fixed.chain_ok != rounds || !ordered) return 1;
    puts("ABA_EPOCH_INVARIANT=PASS"); return 0;
}

// FRONTIER-GH-0034: native scheduler model, executed on aarch64.
// The legacy lane models an unyielding nested future pushed back at the local
// queue head without charging its cooperative budget. The fixed lane charges
// every local poll and checks the global queue at least once per 64 ticks.
use std::collections::VecDeque;
use std::env;

const COOPERATIVE_BUDGET: u32 = 128;
const GLOBAL_FALLBACK_TICKS: u64 = 64;

#[derive(Clone, Debug)]
enum Future {
    UnyieldingNested { id: u32 },
    GlobalCompletion { id: u32 },
}

struct Worker {
    local: VecDeque<Future>,
    global: VecDeque<Future>,
    ticks: u64,
    budget: u32,
    completed_global: Vec<u32>,
    first_global_tick: Option<u64>,
}

impl Worker {
    fn new(global_tasks: u32) -> Self {
        let local = (0..3).map(|id| Future::UnyieldingNested { id }).collect();
        let global = (0..global_tasks).map(|id| Future::GlobalCompletion { id }).collect();
        Self { local, global, ticks: 0, budget: COOPERATIVE_BUDGET,
               completed_global: Vec::new(), first_global_tick: None }
    }

    // Defect reproduction: no budget decrement and no global fallback.
    fn legacy_tick(&mut self) {
        self.ticks += 1;
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }

    // Fix: cooperative budget is charged for every local poll. A global check
    // occurs when the budget empties OR every 64 scheduler ticks, whichever
    // comes first. Unyielding work may continue only after that global check.
    fn fixed_tick(&mut self) {
        self.ticks += 1;
        if self.ticks % GLOBAL_FALLBACK_TICKS == 0 || self.budget == 0 {
            if let Some(Future::GlobalCompletion { id }) = self.global.pop_front() {
                self.completed_global.push(id);
                if self.first_global_tick.is_none() {
                    self.first_global_tick = Some(self.ticks);
                }
            }
            self.budget = COOPERATIVE_BUDGET;
            return;
        }
        if let Some(Future::UnyieldingNested { id }) = self.local.pop_front() {
            self.budget = self.budget.checked_sub(1).expect("budget underflow");
            self.local.push_front(Future::UnyieldingNested { id });
        }
    }
}

fn legacy() {
    let mut w = Worker::new(1);
    for _ in 0..4096 { w.legacy_tick(); }
    assert_eq!(w.completed_global.len(), 0);
    assert_eq!(w.global.len(), 1);
    println!("LEGACY_UNYIELDING_STARVATION_REPRODUCED=YES ticks={} global_completed=0 local_queue_len={} budget_unchanged={}",
             w.ticks, w.local.len(), w.budget);
}

fn fixed() {
    let mut w = Worker::new(1);
    w.fixed_tick();
    let budget_after_first_poll = w.budget;
    while w.completed_global.is_empty() { w.fixed_tick(); }
    assert_eq!(budget_after_first_poll, 127);
    assert_eq!(w.first_global_tick, Some(64));
    assert_eq!(w.completed_global, vec![0]);
    println!("FIXED_COOPERATIVE_BUDGET=PASS budget_after_first_poll={}", budget_after_first_poll);
    println!("FIXED_GLOBAL_FALLBACK=PASS first_global_tick=64 interval_ticks=64 global_completed=1");
}

fn stress() {
    let mut w = Worker::new(64);
    for _ in 0..4096 { w.fixed_tick(); }
    assert_eq!(w.completed_global.len(), 64);
    assert!(w.global.is_empty());
    assert_eq!(w.local.len(), 3, "unyielding local futures remain pending");
    println!("FIXED_GLOBAL_STRESS=PASS ticks={} global_completed=64 first_global_tick={} local_pending=3",
             w.ticks, w.first_global_tick.unwrap());
}

fn main() {
    match env::args().nth(1).as_deref() {
        Some("legacy") => legacy(),
        Some("fixed") => fixed(),
        Some("stress") => stress(),
        _ => { eprintln!("usage: cooperative_budget_model legacy|fixed|stress"); std::process::exit(2); }
    }
}

// FRONTIER-GH-0035: deterministic native CPython subinterpreter lifetime model.
// Negative control: deletion wins before a daemon thread's PyEval_SaveThread.
// Fixed lane: head_mutex serializes interpreter-list deletion with tstate
// acquisition; atomic acquire/release refcount keeps tstate alive until the
// daemon releases the GIL. The negative control detects poison before access,
// avoiding an intentional C undefined-behaviour read in the test process.
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TState {
    atomic_int refs;
    int freed;
    unsigned canary;
} TState;

typedef struct Shared {
    pthread_mutex_t head_mutex;
    pthread_cond_t cv;
    TState *head;
    TState *tstate;
    int stage;
    int daemon_observed_uaf;
    int daemon_completed;
} Shared;

static void init_shared(Shared *s) {
    memset(s, 0, sizeof(*s));
    pthread_mutex_init(&s->head_mutex, NULL);
    pthread_cond_init(&s->cv, NULL);
    s->tstate = calloc(1, sizeof(*s->tstate));
    if (!s->tstate) abort();
    atomic_init(&s->tstate->refs, 1); // interpreter owner's reference
    s->tstate->canary = 0xC0FFEE;
    s->head = s->tstate;
}

static void destroy_shared(Shared *s) {
    free(s->tstate);
    pthread_cond_destroy(&s->cv);
    pthread_mutex_destroy(&s->head_mutex);
}

static void *legacy_daemon(void *arg) {
    Shared *s = arg;
    TState *raw = s->tstate; // unlocked acquisition: defect under test
    pthread_mutex_lock(&s->head_mutex);
    s->stage = 1; // daemon is suspended immediately before SaveThread
    pthread_cond_broadcast(&s->cv);
    while (s->stage < 2) pthread_cond_wait(&s->cv, &s->head_mutex);
    // Poison is checked before any simulated dereference, so the test itself
    // remains defined while still proving that deletion won the lifetime race.
    if (raw->freed) s->daemon_observed_uaf = 1;
    pthread_mutex_unlock(&s->head_mutex);
    return NULL;
}

static int legacy_once(void) {
    Shared s;
    init_shared(&s);
    pthread_t daemon;
    if (pthread_create(&daemon, NULL, legacy_daemon, &s)) return 2;
    pthread_mutex_lock(&s.head_mutex);
    while (s.stage < 1) pthread_cond_wait(&s.cv, &s.head_mutex);
    // Models PyInterpreterState_Delete without head_mutex/list lifetime safety:
    // unlink and poison tstate while the daemon retains its raw pointer.
    s.head = NULL;
    s.tstate->freed = 1;
    atomic_store_explicit(&s.tstate->refs, 0, memory_order_release);
    s.stage = 2;
    pthread_cond_broadcast(&s.cv);
    pthread_mutex_unlock(&s.head_mutex);
    pthread_join(daemon, NULL);
    int reproduced = s.daemon_observed_uaf && atomic_load(&s.tstate->refs) == 0;
    destroy_shared(&s);
    return reproduced ? 0 : 1;
}

static void *fixed_daemon(void *arg) {
    Shared *s = arg;
    pthread_mutex_lock(&s->head_mutex);
    // Acquire head_mutex before touching the interpreter list or tstate refs.
    if (s->head == s->tstate && !s->tstate->freed) {
        atomic_fetch_add_explicit(&s->tstate->refs, 1, memory_order_acquire);
        s->stage = 1; // daemon reference is now independently owned
        pthread_cond_broadcast(&s->cv);
    }
    while (s->stage < 2) pthread_cond_wait(&s->cv, &s->head_mutex);
    pthread_mutex_unlock(&s->head_mutex);

    // Simulated PyEval_SaveThread/GIL release occurs without head_mutex while
    // the atomic daemon reference keeps the object alive.
    if (!s->tstate->freed && s->tstate->canary == 0xC0FFEE)
        s->daemon_completed = 1;
    int old = atomic_fetch_sub_explicit(&s->tstate->refs, 1, memory_order_acq_rel);
    if (old == 2) s->daemon_completed = s->daemon_completed && 1;
    return NULL;
}

static int fixed_once(int *owner_old, int *remaining) {
    Shared s;
    init_shared(&s);
    pthread_t daemon;
    if (pthread_create(&daemon, NULL, fixed_daemon, &s)) return 2;
    pthread_mutex_lock(&s.head_mutex);
    while (s.stage < 1) pthread_cond_wait(&s.cv, &s.head_mutex);
    // Deletion and list unlink are serialized by head_mutex. Drop only the
    // owner's reference; the daemon's atomic reference prevents premature free.
    s.head = NULL;
    *owner_old = atomic_fetch_sub_explicit(&s.tstate->refs, 1, memory_order_acq_rel);
    s.stage = 2;
    pthread_cond_broadcast(&s.cv);
    pthread_mutex_unlock(&s.head_mutex);
    pthread_join(daemon, NULL);
    *remaining = atomic_load_explicit(&s.tstate->refs, memory_order_acquire);
    int ok = *owner_old == 2 && *remaining == 0 && s.daemon_completed &&
             !s.daemon_observed_uaf && !s.tstate->freed;
    destroy_shared(&s);
    return ok ? 0 : 1;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: subinterpreter_lifetime legacy|fixed|stress\n");
        return 2;
    }
    if (!strcmp(argv[1], "legacy")) {
        if (legacy_once()) return 1;
        puts("LEGACY_GIL_DELETE_UAF_REPRODUCED=YES owner_refcount=0 daemon_observed_freed=1");
        return 0;
    }
    int owner_old = 0, remaining = -1;
    if (!strcmp(argv[1], "fixed")) {
        if (fixed_once(&owner_old, &remaining)) return 1;
        puts("FIXED_HEAD_MUTEX=PASS interpreter_unlink_serialized=1");
        printf("FIXED_TSTATE_REFCOUNT=PASS owner_decrement_old=%d final_refs=%d\n", owner_old, remaining);
        puts("FIXED_NO_UAF=PASS daemon_gil_release_completed=1 freed_before_daemon=0");
        return 0;
    }
    if (!strcmp(argv[1], "stress")) {
        for (int i = 0; i < 1000; ++i) {
            if (fixed_once(&owner_old, &remaining)) {
                fprintf(stderr, "fixed stress failed at iteration %d\n", i);
                return 1;
            }
        }
        puts("FIXED_LIFETIME_STRESS=PASS iterations=1000 final_refs=0 uaf=0");
        return 0;
    }
    return 2;
}
